/**
 * Commands from Swift to Rust
 */

public enum Command {
    
    case hoverEntered(screenId: String
    )
    case hoverExited(screenId: String
    )
    case toggleOverlay
    case toggleSurface
    case swipeDown(screenId: String, deltaY: Double
    )
    case screenMetricsChanged(screens: [ScreenMetrics]
    )
    case updateSetting(key: String, value: SettingValue
    )
    case resetSettings
    case trayAddItems(payload: TrayAddPayload
    )
    case trayRemove(itemIds: [String]
    )
    case traySelect(itemId: String, addToSelection: Bool
    )
    case traySelectAll
    case trayClearSelection
    case trayRename(itemId: String, newName: String
    )
    case trayQuickLook(itemIds: [String]
    )
    case trayRevealInFinder(itemId: String
    )
    case trayCopy
    case trayShare(itemIds: [String]
    )
    case widgetAction(widgetId: String, action: String
    )
    case calendarEventsReceived(eventsJson: String
    )
    case mediaStateReceived(stateJson: String
    )
    case cameraListReceived(camerasJson: String
    )
    case volumeChanged(level: Float
    )
    case permissionStatusChanged(calendar: Bool, camera: Bool, automation: Bool
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCommand: FfiConverterRustBuffer {
    typealias SwiftType = Command

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Command {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .hoverEntered(screenId: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .hoverExited(screenId: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .toggleOverlay
        
        case 4: return .toggleSurface
        
        case 5: return .swipeDown(screenId: try FfiConverterString.read(from: &buf), deltaY: try FfiConverterDouble.read(from: &buf)
        )
        
        case 6: return .screenMetricsChanged(screens: try FfiConverterSequenceTypeScreenMetrics.read(from: &buf)
        )
        
        case 7: return .updateSetting(key: try FfiConverterString.read(from: &buf), value: try FfiConverterTypeSettingValue.read(from: &buf)
        )
        
        case 8: return .resetSettings
        
        case 9: return .trayAddItems(payload: try FfiConverterTypeTrayAddPayload.read(from: &buf)
        )
        
        case 10: return .trayRemove(itemIds: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 11: return .traySelect(itemId: try FfiConverterString.read(from: &buf), addToSelection: try FfiConverterBool.read(from: &buf)
        )
        
        case 12: return .traySelectAll
        
        case 13: return .trayClearSelection
        
        case 14: return .trayRename(itemId: try FfiConverterString.read(from: &buf), newName: try FfiConverterString.read(from: &buf)
        )
        
        case 15: return .trayQuickLook(itemIds: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 16: return .trayRevealInFinder(itemId: try FfiConverterString.read(from: &buf)
        )
        
        case 17: return .trayCopy
        
        case 18: return .trayShare(itemIds: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 19: return .widgetAction(widgetId: try FfiConverterString.read(from: &buf), action: try FfiConverterString.read(from: &buf)
        )
        
        case 20: return .calendarEventsReceived(eventsJson: try FfiConverterString.read(from: &buf)
        )
        
        case 21: return .mediaStateReceived(stateJson: try FfiConverterString.read(from: &buf)
        )
        
        case 22: return .cameraListReceived(camerasJson: try FfiConverterString.read(from: &buf)
        )
        
        case 23: return .volumeChanged(level: try FfiConverterFloat.read(from: &buf)
        )
        
        case 24: return .permissionStatusChanged(calendar: try FfiConverterBool.read(from: &buf), camera: try FfiConverterBool.read(from: &buf), automation: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Command, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .hoverEntered(screenId):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(screenId, into: &buf)
            
        
        case let .hoverExited(screenId):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(screenId, into: &buf)
            
        
        case .toggleOverlay:
            writeInt(&buf, Int32(3))
        
        
        case .toggleSurface:
            writeInt(&buf, Int32(4))
        
        
        case let .swipeDown(screenId,deltaY):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(screenId, into: &buf)
            FfiConverterDouble.write(deltaY, into: &buf)
            
        
        case let .screenMetricsChanged(screens):
            writeInt(&buf, Int32(6))
            FfiConverterSequenceTypeScreenMetrics.write(screens, into: &buf)
            
        
        case let .updateSetting(key,value):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(key, into: &buf)
            FfiConverterTypeSettingValue.write(value, into: &buf)
            
        
        case .resetSettings:
            writeInt(&buf, Int32(8))
        
        
        case let .trayAddItems(payload):
            writeInt(&buf, Int32(9))
            FfiConverterTypeTrayAddPayload.write(payload, into: &buf)
            
        
        case let .trayRemove(itemIds):
            writeInt(&buf, Int32(10))
            FfiConverterSequenceString.write(itemIds, into: &buf)
            
        
        case let .traySelect(itemId,addToSelection):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(itemId, into: &buf)
            FfiConverterBool.write(addToSelection, into: &buf)
            
        
        case .traySelectAll:
            writeInt(&buf, Int32(12))
        
        
        case .trayClearSelection:
            writeInt(&buf, Int32(13))
        
        
        case let .trayRename(itemId,newName):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(itemId, into: &buf)
            FfiConverterString.write(newName, into: &buf)
            
        
        case let .trayQuickLook(itemIds):
            writeInt(&buf, Int32(15))
            FfiConverterSequenceString.write(itemIds, into: &buf)
            
        
        case let .trayRevealInFinder(itemId):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(itemId, into: &buf)
            
        
        case .trayCopy:
            writeInt(&buf, Int32(17))
        
        
        case let .trayShare(itemIds):
