        case let .widgetAction(widgetId,action):
            writeInt(&buf, Int32(19))
            FfiConverterString.write(widgetId, into: &buf)
            FfiConverterString.write(action, into: &buf)
            
        
        case let .calendarEventsReceived(eventsJson):
            writeInt(&buf, Int32(20))
            FfiConverterString.write(eventsJson, into: &buf)
            
        
        case let .mediaStateReceived(stateJson):
