        switch variant {
        
        case 1: return .bool(value: try FfiConverterBool.read(from: &buf)
        )
        
        case 2: return .stringValue(value: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .u32(value: try FfiConverterUInt32.read(from: &buf)
        )
        
